mapper.select:

SELECT '优秀 (90-100)' AS `name`, COUNT(CASE WHEN score >= 90 THEN 1 END) AS `value` FROM t_grade WHERE term = #{term}
UNION ALL
SELECT '良好 (80-89)' AS `name`, COUNT(CASE WHEN score >= 80 AND score < 90 THEN 1 END) AS `value` FROM t_grade WHERE term = #{term}
UNION ALL
SELECT '中等 (70-79)' AS `name`, COUNT(CASE WHEN score >= 70 AND score < 80 THEN 1 END) AS `value` FROM t_grade WHERE term = #{term}
UNION ALL
SELECT '及格 (60-69)' AS `name`, COUNT(CASE WHEN score >= 60 AND score < 70 THEN 1 END) AS `value` FROM t_grade WHERE term = #{term}
UNION ALL
SELECT '不及格 (<60)' AS `name`, COUNT(CASE WHEN score < 60 THEN 1 END) AS `value` FROM t_grade WHERE term = #{term}
